eriAlarmXActiveTableURL = MibScalar((1, 3, 6, 1, 4, 1, 193, 183, 6, 1, 3, 4), SnmpAdminString()).setMaxAccess("readonly")
if mibBuilder.loadTexts: eriAlarmXActiveTableURL.setStatus('current')
