eriAlarmXActiveAlarmTable = MibTable((1, 3, 6, 1, 4, 1, 193, 183, 6, 1, 3, 5), ).setMaxAccess("notaccessible")
if mibBuilder.loadTexts: eriAlarmXActiveAlarmTable.setStatus('current')
if mibBuilder.loadTexts: eriAlarmXActiveAlarmTable.setDescription('This table list all active alarms in the system.\r\n                The aspect is the resource view of the alarms,\r\n                not the administrative states and processes\r\n                performed by users. The number of entries,\r\n                active alarms, can be read in\r\n                eriAlarmXActiveNumber. Entries are created when a\r\n                resource has a new alarm state. If the same\r\n                resource has several active alarms, with\r\n                different Alarm Types, this will be represented\r\n                as separate rows. Rows disappear whenever the\r\n                alarm is cleared in the resource.\r\n\r\n                Rows can be changed when an alarm changes severity,\r\n                additional text or additional info. Alarms where\r\n                                the clear state cannot be detected by the resource\r\n                are not represented in this table.\r\n\r\n                The contents of the active alarm table can also\r\n                be fetched using file transfer.\r\n                eriAlarmXActiveTableURL provides a URL to the\r\n                file.')
eriAlarmXActiveAlarmEntry = MibTableRow((1, 3, 6, 1, 4, 1, 193, 183, 6, 1, 3, 5, 1), ).setMaxAccess("notaccessible").setIndexNames((0, "ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveIndex"))
if mibBuilder.loadTexts: eriAlarmXActiveAlarmEntry.setStatus('current')
if mibBuilder.loadTexts: eriAlarmXActiveAlarmEntry.setDescription('One entry in the table holds one active alarm\r\n                for a given resource. Entries are created by the\r\n                system when a resource has a new alarm state.\r\n                Entries are deleted by the system when a resource\r\n                alarm state is cleared.\r\n\r\n                Alarm severity, additional text and additional  \r\n                info can later be changed in a row.')
eriAlarmXActiveIndex = MibTableColumn((1, 3, 6, 1, 4, 1, 193, 183, 6, 1, 3, 5, 1, 1), EriAlarmIndex()).setMaxAccess("notaccessible")
if mibBuilder.loadTexts: eriAlarmXActiveIndex.setStatus('current')
if mibBuilder.loadTexts: eriAlarmXActiveIndex.setDescription("A unique value, greater than zero, for each\r\n                alarm. It is recommended that values are\r\n                assigned contiguously starting from 1. The value\r\n                for each alarm must remain constant at least from\r\n                one re-initialization of the entity to the next\r\n                re-initialization. Note that this index should\r\n                not be used for alarm synchronization purposes\r\n                since the 'logical' index for an alarm is\r\n                - eriAlarmXActiveMajorType\r\n                - eriAlarmXActiveMinorType\r\n                - eriAlarmXActiveYangNodeInstance")
eriAlarmXActiveMajorType = MibTableColumn((1, 3, 6, 1, 4, 1, 193, 183, 6, 1, 3, 5, 1, 2), EriAlarmType()).setMaxAccess("readonly")
if mibBuilder.loadTexts: eriAlarmXActiveMajorType.setStatus('current')
if mibBuilder.loadTexts: eriAlarmXActiveMajorType.setDescription('In combination with eriAlarmXActiveMinorType,\r\n                this provides a unique identification of the\r\n                fault type. Different YANG Schema Nodes and\r\n                instances can share alarm types, but if the same\r\n                YANG resource instance reports the same alarm type, \r\n                it is to be considered as the same alarm state. \r\n                The alarm type is a simplification of the different\r\n                X.733 and 3GPP alarm IRP alarm correlation\r\n                mechanisms based on EventType, ProbableCause,\r\n                SpecificProblem and NotificationId. For systems\r\n                where eriAlarmXActiveMajorType is not needed for\r\n                identification purposes, it is not used and MUST\r\n                be zero-valued.')
eriAlarmXActiveMinorType = MibTableColumn((1, 3, 6, 1, 4, 1, 193, 183, 6, 1, 3, 5, 1, 3), EriAlarmType()).setMaxAccess("readonly")
if mibBuilder.loadTexts: eriAlarmXActiveMinorType.setStatus('current')
if mibBuilder.loadTexts: eriAlarmXActiveMinorType.setDescription('In combination with with\r\n                eriAlarmXActiveMajorType, this provides a unique\r\n                identification of the fault type, not including\r\n                the YANG Schema Node. Different YANG Schema Nodes \r\n                                and instances can share alarm types, but if the \r\n                same YANG resource instance reports the same alarm\r\n                type it is to be considered as the same alarm\r\n                state. The alarm type is a simplification of the\r\n                different X.733 and 3GPP alarm IRP alarm\r\n                correlation mechanisms based on EventType,\r\n                ProbableCause, SpecificProblem and\r\n                NotificationId.')
eriAlarmXActiveSpecificProblem = MibTableColumn((1, 3, 6, 1, 4, 1, 193, 183, 6, 1, 3, 5, 1, 4), EriAlarmSpecificProblem()).setMaxAccess("readonly")
if mibBuilder.loadTexts: eriAlarmXActiveSpecificProblem.setStatus('current')
if mibBuilder.loadTexts: eriAlarmXActiveSpecificProblem.setDescription('This is a clear-text unique identification of\r\n                the alarm type. There is a one-to-one mapping\r\n                between eriAlarmXActiveSpecificProblem and\r\n                [eriAlarmXActiveMajorType,eriAlarmXActiveMinorType]')
