eriAlarmXIndeterminate = NotificationType((1, 3, 6, 1, 4, 1, 193, 183, 6, 2, 0, 1)).setObjects(("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveYangNodeInstance"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveMajorType"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveMinorType"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveSpecificProblem"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveLastSequenceNo"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveEventType"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveEventTime"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveProbableCause"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjAdditionalText"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjMoreAdditionalText"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjResourceId"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjAdditionalInfo"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjMoreAdditionalInfo"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjRecordType"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjSourceIdentifierType"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjSourceIdentifier"))
if mibBuilder.loadTexts: eriAlarmXIndeterminate.setStatus('current')
if mibBuilder.loadTexts: eriAlarmXIndeterminate.setDescription("This notification is sent when a resource\r\n                detects a new alarm state with severity\r\n                indeterminate. The notification is also used to\r\n                change severity, additional text and/or additional \r\n                info of an alarm. The eriAlarmXNObjRecordType\r\n                varbind will indicate whether this is a new alarm\r\n                instance or a change to an existing alarm instance.\r\n                \r\n                The combination of YangNodeInstance \r\n                                and MajorType/MinorType is always unique and can be\r\n                used by management systems to correlate alarm,\r\n                alarm change, and alarm clear. A corresponding\r\n                row will be created in the Alarm Table. The\r\n                sequence number will increase for every\r\n                notification and can be used to detect lost\r\n                notifications.\r\n\r\n                A management system should be prepared for\r\n                appending text to additional text, indicated by\r\n                the eriAlarmXNObjMoreAdditionalText varbind, and\r\n                sent with eriAlarmXAppendInfo.  (Note do not\r\n                confuse this with a change of additional text.)\r\n\r\n                A management system should be prepared for\r\n                appending text to additional info, indicated by\r\n                the eriAlarmXNObjMoreAdditionalInfo varbind, and\r\n                sent with eriAlarmXAppendInfo.  (Note do not\r\n                confuse this with a change of additional info.)\r\n\r\n                                A management system should also be prepared to\r\n                receive a resource ID (OID) identifying the\r\n                alarming resource if the system sending the\r\n                notification can provide that information.  In\r\n                that case, eriAlarmXNObjResourceId will be set to\r\n                'true' and the resource ID will be sent in an\r\n                eriAlarmXAppendInfo notification.")
eriAlarmXWarning = NotificationType((1, 3, 6, 1, 4, 1, 193, 183, 6, 2, 0, 2)).setObjects(("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveYangNodeInstance"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveMajorType"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveMinorType"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveSpecificProblem"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveLastSequenceNo"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveEventType"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveEventTime"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveProbableCause"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjAdditionalText"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjMoreAdditionalText"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjResourceId"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjAdditionalInfo"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjMoreAdditionalInfo"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjRecordType"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjSourceIdentifierType"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjSourceIdentifier"))
if mibBuilder.loadTexts: eriAlarmXWarning.setStatus('current')
if mibBuilder.loadTexts: eriAlarmXWarning.setDescription("This notification is sent when a resource\r\n                detects a new alarm state with severity warning.\r\n                The notification is also used to change severity,\r\n                additional text and/or additional info\r\n                of an alarm. The eriAlarmXNObjRecordType\r\n                varbind will indicate whether this is a new alarm\r\n                instance or a change to an existing alarm instance.\r\n                \r\n                The combination of YangNodeInstance and \r\n                                MajorType/MinorType is always unique and can be\r\n                used by management systems to correlate alarm,\r\n                alarm change, and alarm clear. A corresponding\r\n                row will be created in the Alarm Table,\r\n                (eriAlarmXActiveAlarmTable). The sequence number\r\n                will increase for every notification and can be\r\n                used to detect lost notifications.\r\n\r\n                A management system should be prepared for\r\n                appending text to additional text, indicated by\r\n                the eriAlarmXNObjMoreAdditionalText varbind, and\r\n                sent with eriAlarmXAppendInfo. (Note do not\r\n                confuse this with a change of additional text.)\r\n\r\n                A management system should be prepared for\r\n                appending text to additional info, indicated by\r\n                the eriAlarmXNObjMoreAdditionalInfo varbind, and\r\n                sent with eriAlarmXAppendInfo.  (Note do not\r\n                confuse this with a change of additional info.)\r\n\r\n                A management system should also be prepared to\r\n                receive a resource ID (OID) identifying the\r\n                alarming resource if the system sending the\r\n                notification can provide that information.  In\r\n                that case, eriAlarmXNObjResourceId will be set to\r\n                'true' and the resource ID will be sent in an\r\n                eriAlarmXAppendInfo notification.")
