eriAlarmXCleared = NotificationType((1, 3, 6, 1, 4, 1, 193, 183, 6, 2, 0, 7)).setObjects(("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveYangNodeInstance"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveMajorType"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveMinorType"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveSpecificProblem"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveLastSequenceNo"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveEventType"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveEventTime"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXActiveProbableCause"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjAdditionalText"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjMoreAdditionalText"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjResourceId"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjAdditionalInfo"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjMoreAdditionalInfo"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjSourceIdentifierType"), ("ERICSSON-ALARM-XPATH-MIB", "eriAlarmXNObjSourceIdentifier"))
if mibBuilder.loadTexts: eriAlarmXCleared.setStatus('current')
if mibBuilder.loadTexts: eriAlarmXCleared.setDescription('This notification is sent when a resource\r\n                detects a cleared alarm state. The combination of\r\n                YangNodeInstance and MajorType/MinorType is\r\n                always unique and shall be used by management\r\n                systems to correlate alarm and alarm clear. \r\n                                \r\n                                The corresponding row in the alarm table will be\r\n                deleted, (eriAlarmXActiveAlarmTable). The\r\n                sequence number will increase for every\r\n                notification and can be used to detect lost\r\n                notifications. \r\n                                \r\n                Note that it should not be required to send an\r\n                                append trap for a cleared alarm. Those varbinds\r\n                                which flag that an append trap will follow are \r\n                                kept here for backward compatibility reasons.')
