if mibBuilder.loadTexts: eriAlarmXAppendInfo.setStatus('current')
if mibBuilder.loadTexts: eriAlarmXAppendInfo.setDescription('This notification is sent in order to append\r\n                further info to an alarm notification. It might be\r\n                additional text, additional info or a resource ID \r\n                (OID) identifying the alarming resource using an OID.\r\n                If additional text/info is sent, do not confuse this\r\n                with an actual change of additional text/info which \r\n                is reported using the eriAlarmX<severity>\r\n                notification. \r\n                \r\n                A zero-length string value for\r\n                eriAlarmXNObjAdditionalText means that no\r\n                additional text is being sent in this\r\n                notification.\r\n                \r\n                A zero-length string value for\r\n                eriAlarmXNObjAppendedAdditionalInfo means that no\r\n                additional info is being sent in this\r\n                notification.\r\n                \r\n                A null OID (0.0) value for\r\n                eriAlarmXActiveResourceId means that no resource\r\n                ID is being sent in this notification.')
